function Nav({ item, active, onClick }: { item: { label: string; icon: typeof LayoutDashboard }; active: boolean; onClick: () => void }) { const Icon = item.icon; return <button aria-label={item.label} onClick={onClick} aria-current={active ? "page" : undefined} className={cn("flex w-full items-center gap-3 rounded-xl px-3.5 py-3 text-left text-sm font-bold", active ? "bg-[var(--scene-accent)] text-white shadow-sm" : "text-[var(--scene-muted)] hover:bg-[var(--scene-card)]")}><Icon className="h-[18px] w-[18px]" />{item.label}</button>; }
function Field({ name, label, placeholder, type = "text", dark = false }: { name: string; label: string; placeholder: string; type?: string; dark?: boolean }) { return <label className={cn("block text-sm font-bold", dark && "text-amber-50/90")}>{label}<input aria-label={label} required name={name} type={type} placeholder={placeholder} className={cn("mt-2 w-full rounded-xl border border-[var(--scene-border)] bg-[var(--scene-card)] px-3.5 py-3 text-sm text-[var(--scene-text)] outline-none focus:border-[var(--scene-accent)] focus:ring-2 focus:ring-[var(--scene-accent)]/15", dark && "border-white/15 bg-slate-950/30 text-white placeholder:text-slate-500")} /></label>; }
function Progress({ value, className = "" }: { value: number; className?: string }) { return <div className={cn("h-2 overflow-hidden rounded-full bg-[var(--scene-side)]", className)}><div className="h-full rounded-full bg-[linear-gradient(90deg,var(--scene-accent),var(--scene-accent-alt))]" style={{ width: `${Math.min(100, value)}%` }} /></div>; }
function Heading({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-3 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-700 dark:text-amber-300">{eyebrow}</p><h1 className="mt-2 font-display text-3xl font-bold text-slate-950 dark:text-white sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{text}</p></div>{action}</div>; }
